// LIE Q2 host port: logical activation width stays in Config::expert_ff.
// TensorRef::cols/RowBytes/Expert remain PHYSICAL storage geometry. A later
// HIP route must zero-pad activations; shrinking the weight stride is wrong.
TensorRef RoutedDown(const std::string& name, const Config& c, bool nextn) {
  const auto* info = reader.FindTensor(name);
  const auto* logical_meta = reader.FindMetadata("ds4.qwen4.down.logical_input");
  const auto* physical_meta = reader.FindMetadata("ds4.qwen4.down.physical_input");
  const bool annotated = !nextn && (logical_meta || physical_meta);
  const bool q2 = info && info->type == GgmlType::kQ2_K;
  if (annotated || q2) {
    const auto logical = reader.GetMetadataUint32("ds4.qwen4.down.logical_input");
    const auto physical = reader.GetMetadataUint32("ds4.qwen4.down.physical_input");
    if (nextn || !logical_meta || !physical_meta ||
        logical_meta->type != core::GgufValueType::kUint32 ||
        physical_meta->type != core::GgufValueType::kUint32 ||
        !logical || !physical || *logical != c.expert_ff ||
        *logical != 640 || *physical != 768) {
      Fail("invalid or missing Q2 down padding metadata: " + name);
      return {};
    }
    if (!q2) {
      Fail("Q2 down padding format mismatch: " + name);
      return {};
    }
    return Get(name, *physical, c.hidden_size, c.num_experts,
               {GgmlType::kQ2_K});
  }
  // Do not broaden MXFP4/MTP or arbitrary padded layouts by recognition alone.
  return Get(name, c.expert_ff, c.hidden_size, c.num_experts,
             {GgmlType::kQ4_K, GgmlType::kQ5_K, GgmlType::kQ6_K,
              GgmlType::kQ5_1, GgmlType::kQ8_0});
}

